130	 * - `release` — the run is over and nothing is coming: write the ending that answers the
131	 *   claim and hand the node back to a person.
132	 * - `hold` — something may still hold it, or a park's collection is legitimately still on
133	 *   its way. Write nothing.
134	 * - `undetermined` — the question could not be answered. Write nothing either, but say
135	 *   so: silence here is indistinguishable from "there was nothing to do".
136	 */
137	export type LockVerdict = "release" | "hold" | "undetermined";
138	
139	/**
140	 * The judgement about one node.
141	 *
142	 * A lock that is NOT parked has no legitimate resumer: the run took the turn and nothing
143	 * but an ending can release it, so "the run is over" is the whole answer.
144	 *
145	 * A PARK does have one — the aggregation — and that is why three more facts are required
146	 * before releasing one: nothing is left open under the node, the grace has passed, and the
147	 * links could be read at all. All three are about not racing the machinery's own resume. A
148	 * park released a sweep early would post "nothing was decided" beside a parent that then
149	 * decides something.
150	 *
151	 * `claim` is absent in one real state: a person removed the claim by hand to get out of a
152	 * lock and left the park standing, which before this was the only way out of a stuck one.
153	 * There is no run to ask about then, and the park clock plus the open children are what is
154	 * left — which is enough, because a park is the newer of the two facts and carries its own
155	 * ending.
156	 */
157	export function lockVerdict(args: {
158	  /** The open claim, or `undefined` when the thread leaves none. */
159	  readonly claim: ClaimLock | undefined;
160	  /** Whether the thread's newest event is a `waiting` ending — a parked turn (#208). */
161	  readonly parked: boolean;
162	  /** When that ending was written. Only read when `parked`. */
163	  readonly parkedSince: string;
164	  /**
165	   * Open work under the node — sub-issues AND pull requests — or `undefined` when the
166	   * links could not be read.
167	   *
168	   * Both lists, because a park waits on whichever it started: a sub-issue
169	   * (`launch_sub_agent`) or a pull request (`create_pr`). Counting only sub-issues reads a
170	   * leaf issue's `create_pr` park as "nothing is open" while its pull request is in review.
171	   */
172	  readonly openUnder: number | undefined;
173	  /** What GitHub says about the claim's run. Ignored when there is no claim. */
174	  readonly run: RunStatusRead;
175	  readonly nowMs: number;
176	}): LockVerdict {
177	  if (args.parked) {
178	    if (args.openUnder === undefined) return "undetermined";
179	    if (args.openUnder > 0) return "hold";
180	    if (!parkOverdue(args.parkedSince, args.nowMs)) return "hold";
181	    // The park is overdue and nothing is open under it. A resume that IS dispatched
182	    // claims the parked ask first, so a claim made after the park is a live run holding
183	    // the ball and its own ending will answer — that is what this last check reads.
184	    if (args.claim === undefined) return "release";
185	    const parkedClaim = claimFreshness(args.claim, args.run, args.nowMs);
186	    return parkedClaim === "fresh" ? "hold" : parkedClaim === "unknown" ? "undetermined" : "release";
187	  }
188	  // Nothing claims the turn, so no reader holds it: the guard keeps a person's comment
189	  // and there is nothing for a sweep to release.
190	  if (args.claim === undefined) return "hold";
191	  const freshness = claimFreshness(args.claim, args.run, args.nowMs);
192	  if (freshness === "unknown") return "undetermined";
193	  return freshness === "fresh" ? "hold" : "release";
194	}
195	
196	/**
197	 * Whether the lock is one NOBODY is coming back for — the guard's question.
198	 *
199	 * The guard deletes a person's comment made while the ball is with an agent, and until now
200	 * "with an agent" was read off the claim alone: a `took` line with no ending after it. A
201	 * claim outlives its run whenever a run dies without reporting, and in that state the
202	 * guard removes every comment a person writes — the node reads as busy forever, nothing
203	 * heals the thread, and there is no way back in (#462).
204	 *
205	 * So the guard asks the same question the sweep does, of the same function. Deliberately
206	 * narrower than `lockVerdict`, which answers a different question — whether the SWEEP
207	 * should write an ending. The guard writes nothing and must not: its answer is only
208	 * "remove this comment or leave it", and leaving it is the safe side once the run is gone,
209	 * because the comment then reaches a node whose turn nothing holds.
210	 *
211	 * Two shapes are NOT abandoned however old the claim looks, and both are about not racing
212	 * work that is really there:
213	 *
214	 *   - a PARK. The run ended on purpose and the turn is held open for the aggregation,
215	 *     which resumes the node and reads what was written during the wait (#208). The park's
216	 *     own clock is the sweep's business — it releases a missed one after the grace — so
217	 *     the guard keeps its rule for the length of the wait.
218	 *   - a claim nobody can judge (an unreadable run, an unreadable time). `unknown` is not
219	 *     `stale`: removing a live run's comments is the harm this guard exists to prevent, so
220	 *     a failed read keeps the old behaviour.
221	 */
222	export function abandonedClaim(args: {
223	  readonly claim: ClaimLock | undefined;
224	  readonly parked: boolean;
225	  readonly run: RunStatusRead;
226	  readonly nowMs: number;
227	}): boolean {
228	  if (args.parked || args.claim === undefined) return false;
229	  return claimFreshness(args.claim, args.run, args.nowMs) === "stale";
230	}

