960	  // session died mid-work. Every one of them looks identical from here.
961	  //
962	  // So the question is asked of EVIDENCE rather than of the file: has anything
963	  // already ended this run's turn on the thread? The one thing that says yes is the
964	  // record a session-ending tool writes when it posts its comment
965	  // (`ending-comment.ts`, in the run's own directory) -- and where that record
966	  // exists the footer is appended onto THAT comment, because it is the one that
967	  // ended this run.
968	  //
969	  // No record means nothing spoke for this run, and this step is the only thing left
970	  // that can. That direction is deliberate: a second comment under one a tool already
971	  // posted is noise a person reads past, while a run that ends with nothing on its
972	  // thread deletes the `atomaton:ended` tag that releases the thread's guard -- the
973	  // defect that let a guard delete a person's later comments forever (#194, #186).
974	  // Holding a thread's guard on a guess about another component is the larger harm.
975	  let output = redacted;
976	  let salvaged = false;
977	  let wroteNothing = false;
978	  // A step that failed left no ending behind: the reads that turn atoma's own exit into
979	  // one run only for the two statuses atoma handles itself, and a crash writes the
980	  // boundary flag instead. So the step's outcome IS the ending in that shape, and the
981	  // word it becomes is the one every decision below already keys off.
982	  const stepFailed = values.outcome === "failure";
983	  const endedBecause = values["ended-because"] || (stepFailed ? "failed" : "");
984	  const endedEarly = cutShort(endedBecause);
985	  const failed = endedBecause === "failed";
986	
987	  if (!output.trim() && endedEarly) {
988	    const last = lastAgentText(values.session, Number(values["messages-before"]));
989	    if (last !== undefined) {
990	      output = redact(last);
991	      salvaged = true;
992	      console.error("salvaged the agent's last message from the session (cut short)");
993	    }
994	  }
995	
996	  if (!output.trim()) {
997	    // Not asked of a failed step: what a session-ending tool recorded is the comment
998	    // THAT tool posted, and the old arrangement posted the failure notice beside it
999	    // anyway — the tool says what the run did, the notice says that it then died, and
1000	    // only the second is an ending. Reading the record here would turn a crash into a
1001	    // footer on a comment that reads as a hand-off.
1002	    const ending = stepFailed ? undefined : readEndingComment(values["ending-comment"]);
1003	    if (ending) {
1004	      console.error(`appending the result footer onto the tool's ending comment ${ending.commentId} (on ${ending.node})`);
1005	      appendFooter({
1006	        repo: process.env.GITHUB_REPOSITORY ?? "",
1007	        commentId: ending.commentId,
1008	        agent: values.agent,
1009	        runUrl: values["run-url"],
1010	        tokenLine: tokenUsageLine(values["logs-file"] ?? ""),
1011	        toolTrouble: toolTroubleLine(readSession(values.session), Number(values["messages-before"])),
1012	      });
1013	      return;
1014	    }
1015	    if (failed) {
1016	      // Nothing to show, and nothing to invent: the failure notice itself is the body
1017	      // (#441), so `output` stays empty rather than gaining a placeholder under it.
1018	      // The same arm answers a hard crash now — the step failed, no ending was recorded,
1019	      // and this is the only writer left to say so.
1020	      console.error("the run failed with nothing to report -- posting the failure notice rather than nothing.");
1021	    } else if (endedEarly) {
1022	      // It is wrong for a run that was cut short, and this is the common shape
1023	      // rather than the odd one. A stop lands at the next turn boundary, so a run
1024	      // reading files when it arrives has said nothing at all and there is nothing
1025	      // to salvage -- a run that spent nine iterations in tool calls and produced
1026	      // no assistant text is the observed case (#831). Skipping there drops the
1027	      // machinery's own sentence along with the agent's silence: that it stopped,
1028	      // that the session survived, and how to resume.
1029	      wroteNothing = true;
1030	      output = endedBecause === "stopped"
1031	        ? "_This run was stopped before it said anything._"
1032	        : `_This run ${howItWasCutShort(endedBecause)} before it said anything._`;
1033	      console.error("the run was cut short with nothing to report -- posting the notice rather than nothing.");
1034	    } else {
1035	      // A run that ended of its own accord without saying anything: the shape of
1036	      // #194 (an empty final response `completed`) and #186 (no session at all).
1037	      // Same treatment, no-report wording: the comment is the machinery's only
1038	      // sentence on this thread, the `atomaton:ended` tag under it is what releases
1039	      // the thread's guard, and the mention is what fetches a person -- see
1040	      // `completion-mention.ts`, which already forces one for a run the session
1041	      // shows reported nothing.
1042	      wroteNothing = true;
1043	      output = "_This run ended without saying anything._";
1044	      console.error(
1045	        "atomaton_output.txt is empty and no session-ending tool recorded a comment " +
1046	          "-- posting the no-report notice rather than skipping.",
1047	      );
1048	    }
1049	  }
1050	
1051	  // A failed run reached no closing judgement of its own, so whatever text it left is
1052	  // a fragment of the work rather than a conclusion -- the warning a salvage gets.
1053	  // Without it the comment would present the last thing said before the failure as a
1054	  // result, which is the false claim `salvaged` exists to prevent.
1055	  if (failed && !salvaged && output.trim() !== "") salvaged = true;
1056	
1057	  // Checked on the way out for the same reason it is redacted on the way out:
1058	  // this text is whatever the agent decided to write, and a comment is the one
1059	  // place it reaches people. A `@name` here notifies a real account -- see
1060	  // `domain/work/mention.ts` for why a name it read somewhere is enough.
1061	  //
1062	  // The mention the RUNNER adds is not part of this. It is put in by
1063	  // `buildCommentBody` below from a login `resolveNotify` produced, and never
1064	  // passes through here.
1065	  //
1066	  // Three texts are not a call, and every mention in them is escaped rather than
1067	  // confirmed: a salvaged fragment, a run that was cut short (its last message is
1068	  // where the stop landed, not a hand-off), and a closing message the one-call rule
1069	  // refused. In all three a name is a name in a sentence, not somebody being asked,
1070	  // and letting one through would notify a person on the strength of a sentence the
1071	  // machinery already knows is not the run's call. The notice under the text says
1072	  // which of the three it was, and the machinery's own mention is what reaches
1073	  // somebody.
1074	  const endingInvalid = isTrue(values["ending-invalid"]);
1075	  const notACall = endingInvalid || salvaged || endedEarly;
1076	  // The two lists the run was given, from the same file the notice and the ending
1077	  // check read: one read of the thread at the start of the run, not three that have
1078	  // to agree. `known` may notify; `callable` may be handed the turn.
1079	  //
1080	  // Nothing in a text that was not a call is allowed to notify — a salvaged fragment,
1081	  // a run that was cut short, a message the one-call rule refused. Every mention in
1082	  // those is escaped, the owner's included: the machinery's own sentence is what
1083	  // reaches them, and a live mention beside it would say "your turn" while that
1084	  // sentence says nothing is running.
1085	  const callees = readCalleesFile(values["people-file"]);

