424	function lockOf<T extends DatedEntry>(entries: readonly T[], shaped: ShapedThread<T>): ThreadLock {
425	  const park = shaped.events[shaped.events.length - 1] === "waiting" ? newestWaiting(entries) : undefined;
426	  const open = shaped.openClaim;
427	  const lock: ThreadLock = park === undefined ? {} : { park };
428	  if (open === undefined) return lock;
429	  const at = newestWith(entries, (body) => {
430	    const claim = readers.claim(body);
